SELECT V.name, V.Model_year, V.Type_of_powertrain, V.Cost_per_25_miles, V.Annual_fuel_cost, V.Notes FROM Vehicles V JOIN Renting_history RH ON V.id = RH.vehicles_id ORDER BY V.Model_year DESC;
