SELECT V.Type_of_powertrain, C.name FROM Customers C JOIN Renting_history R ON C.id = R.customer_id JOIN Vehicles V ON R.vehicles_id = V.id WHERE R.Model_year IN ('2014', '2013')
SELECT DISTINCT V.Type_of_powertrain FROM Vehicles V JOIN Renting_history R ON V.id = R.vehicles_id WHERE R.customer_id = (SELECT id FROM Customers WHERE age = 2013 OR age = 2014) AND R.Model_year IN (2013, 2014)
SELECT Discount.name, COUNT(Vehicles.id) AS count_of_vehicles_per_type FROM Discount JOIN Renting_history ON Discount.id = Renting_history.discount_id JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id GROUP BY Discount.name
SELECT COUNT(DISTINCT Type_of_powertrain), COUNT(DISTINCT Type_of_powertrain) AS total FROM Vehicles;
SELECT V.Type_of_powertrain, COUNT(V.id) AS vehicle_count FROM Vehicles V JOIN Renting_history R ON V.id = R.vehicles_id GROUP BY V.Type_of_powertrain ORDER BY COUNT(V.id) DESC LIMIT 1;
SELECT Discount.name, COUNT(Vehicles.id) AS most_common_count FROM Discount JOIN Renting_history ON Discount.id = Renting_history.discount_id JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id GROUP BY Discount.id, Discount.name ORDER BY COUNT(Vehicles.id) DESC;
SELECT Customers.name, Customers.age, Customers.membership_credit, Vehicles.Combined_fuel_economy_rate, Vehicles.City_fuel_economy_rate, Vehicles.Highway_fuel_economy_rate, Vehicles.Annual_fuel_cost, Vehicles.Cost_per_25_miles FROM Customers JOIN Vehicles ON Customers.id = Vehicles.customer_id;
SELECT C.name, V.Annual_fuel_cost, AVG(V.Annual_fuel_cost) AS average_annual_fuel_cost, MAX(V.Annual_fuel_cost) AS maximum_annual_fuel_cost, MIN(V.Annual_fuel_cost) AS minimum_annual_fuel_cost FROM Customers C JOIN Vehicles V ON C.id = V.customer_id GROUP BY C.id, V.id;
