SELECT V.Type_of_powertrain, AVG(V.Annual_fuel_cost) AS Average_Annual_Fuel_Cost FROM Vehicles V JOIN Renting_history RH ON V.id = RH.vehicles_id JOIN Customers C ON RH.customer_id = C.id GROUP BY V.Type_of_powertrain
