SELECT Customers.name, Customers.age FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id WHERE Renting_history.discount_id = Discount.id AND Discount.membership_credit = (SELECT MAX(membership_credit) FROM Discount)
SELECT Customers.name, Customers.age FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id JOIN Discount ON Renting_history.discount_id = Discount.id GROUP BY Customers.name, Customers.age ORDER BY Customers.age DESC LIMIT 1;
SELECT AVG(age) FROM Customers WHERE membership_credit > (SELECT AVG(membership_credit) FROM Customers)
SELECT AVG(age) FROM Customers WHERE membership_credit > (SELECT AVG(membership_credit) FROM Customers)
SELECT Customers.id, Customers.name, Customers.age, Customers.membership_credit, Discount.id, Discount.name, Discount.membership_credit, Vehicles.id, Vehicles.name, Vehicles.Model_year, Vehicles.Type_of_powertrain, Vehicles.Combined_fuel_economy_rate, Vehicles.City_fuel_economy_rate, Vehicles.Highway_fuel_economy_rate, Vehicles.Cost_per_25_miles, Vehicles.Annual_fuel_cost, Vehicles.Notes FROM Customers INNER JOIN Discount ON Customers.id = Discount.id INNER JOIN Vehicles ON Vehicles.id = Discount.vehicles_id;
SELECT Customers.id, Customers.name, Customers.age, Customers.membership_credit, Discount.id, Discount.name, Discount.membership_credit, Vehicles.id, Vehicles.name, Vehicles.Model_year, Vehicles.Type_of_powertrain, Vehicles.Combined_fuel_economy_rate, Vehicles.City_fuel_economy_rate, Vehicles.Highway_fuel_economy_rate, Vehicles.Cost_per_25_miles, Vehicles.Annual_fuel_cost, Vehicles.Notes FROM Customers JOIN Discount ON Customers.id = Discount.discount_id JOIN Vehicles ON Vehicles.id = Renting_history.vehicles_id;
SELECT Customers.name, SUM(Renting_history.total_hours) AS total_hours FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id GROUP BY Customers.id
SELECT Customers.name, SUM(Renting_history.total_hours) AS total_rental_hours FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id GROUP BY Customers.id
SELECT Customers.name FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id WHERE Renting_history.discount_id IS NULL;
SELECT DISTINCT Customers.name FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id WHERE Renting_history.discount_id IS NULL OR Renting_history.vehicles_id IS NULL
SELECT Customers.name FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id WHERE Renting_history.discount_id IS NOT NULL AND Renting_history.vehicles_id IS NOT NULL AND Renting_history.total_hours >= 2
SELECT Customers.name, Discount.name FROM Customers JOIN Discount ON Customers.id = Discount.id WHERE Customers.id IN (SELECT customer_id FROM Renting_history WHERE discount_id = Discount.id AND vehicles_id = Vehicles.id AND total_hours > 0)
SELECT Customers.name, Vehicles.Model_year FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id INNER JOIN Discount ON Renting_history.discount_id = Discount.id INNER JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id GROUP BY Customers.name, Vehicles.Model_year ORDER BY COUNT(Renting_history.id) DESC LIMIT 1;
SELECT C.name, V.Model_year FROM Customers C JOIN Vehicles V ON C.id = V.id JOIN Renting_history RH ON V.id = RH.vehicles_id GROUP BY C.name, V.Model_year ORDER BY RH.total_hours DESC LIMIT 1;
SELECT Vehicles.name, Rentals.total_hours FROM Rentals INNER JOIN Vehicles ON Rentals.vehicles_id = Vehicles.id ORDER BY Rentals.total_hours DESC;
SELECT name, total_hours FROM Renting_history JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id ORDER BY total_hours DESC;
SELECT Discount.name, COUNT(Renting_history.id) AS total_renting_history FROM Customers INNER JOIN Renting_history ON Customers.id = Renting_history.customer_id JOIN Discount ON Renting_history.discount_id = Discount.id GROUP BY Discount.id, Discount.name ORDER BY total_renting_history DESC LIMIT 1;
SELECT Discount.name FROM Discount JOIN Renting_history ON Discount.id = Renting_history.discount_id JOIN Customers ON Renting_history.customer_id = Customers.id GROUP BY Discount.id ORDER BY Renting_history.total_hours DESC LIMIT 1
SELECT Customers.name, Vehicles.Type_of_powertrain FROM Customers JOIN Renting_history ON Customers.id = Renting_history.customer_id JOIN Vehicles ON Renting_history.vehicles_id = Vehicles.id WHERE Vehicles.Combined_fuel_economy_rate > 30;
SELECT name, Type_of_powertrain FROM Vehicles INNER JOIN Renting_history ON Vehicles.id = Renting_history.vehicles_id WHERE total_hours > 30;
SELECT AVG(Vehicles.City_fuel_economy_rate) AS average_city_fuel_rate, AVG(Vehicles.Highway_fuel_economy_rate) AS average_highway_fuel_rate FROM Vehicles INNER JOIN Customers ON Vehicles.customer_id = Customers.id;
SELECT AVG(City_fuel_economy_rate), AVG(Highway_fuel_economy_rate) FROM Vehicles;
SELECT AVG(loan_amount) FROM Student_Loans;
SELECT AVG(amount_of_loan) FROM Student_Loans;
