{ "sql": "SELECT s.student_id, s.bio_data, s.student_details, s.student_events, s.student_loans, s.addresses, s.detention, s.classes, s.achievements, s.achievement_type_code, s.achievement_details, s.achievement_date, s.achievement_summary, s.loan_amount, s.loan_date\nFROM Students s\nJOIN Transcripts t ON s.student_id = t.student_id\nJOIN Behaviour_Monitoring b ON s.student_id = b.student_id\nJOIN Student_Events se ON s.student_id = se.student_id\nJOIN Student_Loans sl ON s.student_id = sl.student_id\nJOIN Classes cl ON s.student_id = cl.student_id\nJOIN Addresses a ON s.addresses ON s.address_id = a.address_id\nJOIN Detention d ON s.student_id = d.student_id\nJOIN Achievements a2 ON s.student_id = a2.student_id\nJOIN Ref_Achievement_Type a3 ON a2.achievement_type_code = a3.achievement_type_code\nJOIN Ref_Detention_Type d2 ON d.detention_type_code = d2.detention_type_code\nJOIN Ref_Address_Types a4 ON a.address_type_code = a4.address_type_code\nJOIN Ref_Achievement_Type a5 ON a2.achievement_type_code = a5.achievement_type_code\nJOIN Ref_Address_Types a6 ON a.address_type_code = a6.address_type_code\nJOIN Ref_Detention_Type d3 ON d.detention_type_code = d3.detention_type_code\nJOIN Ref_Achievement_Type a7 ON a2.achievement_type_code = a7.achievement_type_code\nJOIN Ref_Address_Types a8 ON a.address_type_code = a8.address_type_code\nJOIN Ref_Detention_Type d4 ON d.detention_type_code = d4.detention_type_code\nJOIN Ref_Achievement_Type a9 ON a2.achievement_type_code = a9.achievement_type_code\nJOIN Ref_Address_Types a10 ON a.address_type_code = a10.address_type_code\nJOIN Ref_Detention_Type d5 ON d.detention_type_code = d5.detention_type_code\nJOIN Ref_Achievement_Type a11 ON a2.achievement_type_code = a11.achievement_type_code\nJOIN Ref_Address_Types a12 ON a.address_type_code = a12.address_type_code\nJOIN Ref_Detention_Type d6 ON d.detention_type_code = d6.detention_type_code\nJOIN Ref_Achievement_Type a13 ON a2.achievement_type_code = a13.achievement_type_code\nJOI