SELECT Students.bio_data, Transcripts.date_of_transcript FROM Students INNER JOIN Transcripts ON Students.student_id = Transcripts.student_id;
SELECT student_id, date_of_transcript, transcript_details FROM Transcripts INNER JOIN Students ON Transcripts.student_id = Students.student_id;
SELECT b.behaviour_monitoring_details, COUNT(b.behaviour_monitoring_details) AS count FROM Behaviour_Monitoring b JOIN Students s ON b.student_id = s.student_id GROUP BY b.behaviour_monitoring_details;
SELECT student_id, behaviour_monitoring_details, COUNT(*) AS count FROM Behaviour_Monitoring GROUP BY student_id ORDER BY count DESC;
SELECT Students.student_id, Students.bio_data, Students.student_details, Detention.datetime_detention_start, Detention.detention_summary FROM Students JOIN Detention ON Students.student_id = Detention.student_id WHERE Detention.detention_summary IS NOT NULL ORDER BY Detention.datetime_detention_start DESC;
SELECT S.student_id, S.bio_data, S.student_details, B.behaviour_monitoring_details, T.transcript_details FROM Students S JOIN Behaviour_Monitoring B ON S.student_id = B.student_id JOIN Transcripts T ON S.student_id = T.student_id WHERE S.student_details NOT IN (SELECT student_details FROM Transcripts) AND B.behaviour_monitoring_details NOT IN (SELECT behaviour_monitoring_details FROM Transcripts) AND (T.transcript_details IS NOT NULL OR B.behaviour_monitoring_details IS NOT NULL) ORDER BY S.student_id;
SELECT Students.student_id, Students.bio_data, Students.student_details, Students.student_details FROM Students INNER JOIN Transcripts ON Transcripts.student_id = Students.student_id INNER JOIN Behaviour_Monitoring ON Behaviour_Monitoring.student_id = Students.student_id WHERE Behaviour_Monitoring.behaviour_monitoring_details = (SELECT MAX(behaviour_monitoring_details) FROM Behaviour_Monitoring WHERE student_id = Students.student_id)
SELECT student_id, bio_data, behaviour_monitoring_details FROM Students JOIN Behaviour_Monitoring ON Students.student_id = Behaviour_Monitoring.student_id WHERE Behaviour_Monitoring_details IS NOT NULL ORDER BY behaviour_monitoring_details DESC;
SELECT S.student_id, S.bio_data, S.student_details, D.event_date AS event_date FROM Students S JOIN Detention D ON S.student_id = D.student_id;
SELECT S.student_id, S.bio_data, S.student_details, S.event_date, S.other_details, T.date_of_transcript, T.transcript_details, B.behaviour_monitoring_details, A.address_details, RE.T.event_type_description, RE.Achievement_Type.achievement_type_description, RE.Detention_Type.detention_type_description FROM Students S JOIN Transcripts T ON S.student_id = T.student_id JOIN Behaviour_Monitoring B ON S.student_id = B.student_id JOIN Student_Events T2 ON S.student_id = T2.student_id JOIN Ref_Event_Types T3 ON T2.event_type_code = T3.event_type_code JOIN Ref_Achievement_Type A ON T2.achievement_type_code = A.achievement_type_code JOIN Ref_Detention_Type D ON T2.detention_type_code = D.detention_type_code JOIN Addresses A2 ON S.student_id = A2.address_id JOIN Ref_Address_Types R ON A2.address_type_code = R.address_type_code JOIN Detention D2 ON S.student_id = D2.student_id GROUP BY S.student_id, S.bio_data, S.student_details, S.event_date, S.other_details, T.date_of_transcript, T.transcript_details, B.behaviour_monitoring_details, A.address_details, RE.T.event_type_description, RE.Achievement_Type.achievement_type_description, RE.Detention_Type.detention_type_description;
SELECT COUNT(*) AS total_students, event_type_description AS event_type, transcript_details AS description FROM Student_Events JOIN Ref_Event_Types ON Student_Events.event_type_code = Ref_Event_Types.event_type_code GROUP BY event_type ORDER BY COUNT(*) DESC;
SELECT COUNT(*) AS number_of_students, Ref_Event_Types.event_type_code AS event_type_code, Ref_Event_Types.event_type_description AS event_type_description FROM Student_Events INNER JOIN Ref_Event_Types ON Student_Events.event_type_code = Ref_Event_Types.event_type_code GROUP BY event_type_code ORDER BY number_of_students DESC;
SELECT A.achievement_details, A.achievement_type_description AS type_description FROM Achievements A;
SELECT achievement_type_code, achievement_details, type_description FROM Ref_Achievement_Type JOIN Achievements ON Achievements.achievement_type_code = Ref_Achievement_Type.achievement_type_code;
SELECT COUNT(DISTINCT student_id) FROM Students AS s JOIN Transcripts t ON s.student_id = t.student_id JOIN Behaviour_Monitoring b ON s.student_id = b.student_id JOIN Detention d ON s.student_id = d.student_id JOIN Students_Addresses sa ON s.student_id = sa.student_id JOIN Ref_Address_Types r ON sa.address_type_code = r.address_type_code JOIN Ref_Detention_Type dt ON d.detention_type_code = dt.detention_type_code;
SELECT COUNT(DISTINCT t.student_id) FROM Transcripts t JOIN Students s ON t.student_id = s.student_id JOIN Students_Addresses sa ON s.student_id = sa.student_id JOIN Detention d ON sa.student_id = d.student_id GROUP BY s.student_id;
SELECT Transcripts.date_of_transcript, Transcripts.transcript_details FROM Transcripts INNER JOIN Students ON Transcripts.student_id = Students.student_id;
SELECT Transcripts.date_of_transcript, Transcripts.transcript_details AS detail FROM Transcripts INNER JOIN Students ON Transcripts.student_id = Students.student_id;
SELECT Ref_Achievement_Type.achievement_type_code, Ref_Achievement_Type.achievement_details, Detention.datetime_detention_end AS achievement_date FROM Ref_Achievement_Type JOIN Detention ON Ref_Achievement_Type.achievement_type_code = Detention.achievement_type_code WHERE Detention.student_id = Students.student_id;
SELECT Transcripts.transcript_id, Transcripts.date_of_transcript, Transcripts.transcript_details, Students.student_id, Students.bio_data, Students.student_details FROM Transcripts JOIN Students ON Transcripts.student_id = Students.student_id WHERE Transcripts.date_of_transcript IS NOT NULL;
SELECT detention.datetime_detention_start, detention.datetime_detention_end FROM Detention INNER JOIN Students ON Detention.student_id = Students.student_id;
SELECT detention.datetime_detention_start, detention.datetime_detention_end, detention.detention_summary FROM Detention detention JOIN Student_Events student_events ON detention.student_id = student_events.student_id JOIN Ref_Detention_Type detention_type ON detention.detention_type_code = detention_type.detention_type_code JOIN Ref_Address_Types address_type ON detention.student_id = student_events.student_id JOIN Addresses address ON student_events.address_id = address.address_id JOIN Ref_Address_Types address_type ON detention.student_id = student_events.student_id JOIN Ref_Address_Types address_type ON detention.student_id = student_events.student_id JOIN Ref_Address_Types address_type ON detention.student_id = student_events.student_id JOIN Ref_Address_Types address_type ON detention.student_id = student_events.student_id JOIN Ref_Address_Types address_type ON detention.student_id = student_events.student_id
SELECT Students.student_id, Students.bio_data, Students.student_details FROM Students INNER JOIN Transcripts ON Transcripts.student_id = Students.student_id WHERE Transcripts.transcript_details LIKE '%Suite%';
SELECT student_id, bio_data, achievement_details, date_achievement, achievement_type_code FROM Students INNER JOIN Achievements ON Students.student_id = Achievements.student_id WHERE bio_data LIKE '%Suite%'
SELECT t.student_id, s.student_details, b.behaviour_monitoring_details, c.class_details FROM Students s JOIN Classes c ON s.student_id = c.student_id JOIN Behaviour_Monitoring b ON c.teacher_id = b.student_id;
SELECT s.student_id, t.transcript_details, t.date_of_transcript, t.behaviour_monitoring_details, t.transcript_id, t.student_id, t.date_of_transcript FROM Students s JOIN Transcripts t ON s.student_id = t.student_id JOIN Behaviour_Monitoring b ON s.student_id = b.student_id JOIN Student_Events e ON s.student_id = e.student_id JOIN Ref_Event_Types e_type ON e.event_type_code = e_type.event_type_code JOIN Ref_Address_Types e_type_address ON e.student_address_id = e_type_address.address_type_code JOIN Addresses a ON e.student_address_id = a.address_id JOIN Detention d ON s.student_id = d.student_id JOIN Ref_Detention_Type d_type ON d.detention_type_code = d_type.detention_type_code JOIN Ref_Address_Types d_type_address ON d.student_address_id = d_type_address.address_type_code JOIN Ref_Achievement_Type a_type ON e.achievement_type_code = a_type.achievement_type_code JOIN Achievements a_achievement ON e.achievement_id = a_achievement.achievement_id;
