SELECT Students.bio_data, Students.student_id, Students.student_details, Students_Addresses.address_id, Addresses.address_details FROM Students INNER JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id INNER JOIN Addresses ON Students_Addresses.address_id = Addresses.address_id WHERE Student_Loans.amount_of_loan > (SELECT AVG(Student_Loans.amount_of_loan) FROM Student_Loans)
