SELECT countries.name, languages.name AS official_language FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id GROUP BY countries.name ORDER BY languages.name DESC LIMIT 1
SELECT languages.name AS language, countries.name AS country, COUNT(*) AS count FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id GROUP BY languages.name, countries.name ORDER BY count DESC LIMIT 1;
SELECT l.name, o.country_id FROM languages l JOIN official_languages o ON l.id = o.language_id WHERE o.country_id IN (SELECT c.id FROM countries c WHERE c.official_languages_count >= 2)
SELECT DISTINCT l.name AS language, c.name AS country FROM languages l JOIN countries c ON l.id = c.id;
SELECT AVG(countries.overall_score) FROM countries WHERE countries.name LIKE 'English' AND countries.id IN (SELECT id FROM official_languages WHERE language_id IN (SELECT language_id FROM languages WHERE name = 'English'))
SELECT AVG(countries.overall_score) FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE languages.name = 'English'
SELECT languages.name, countries.name, official_languages.name FROM languages JOIN countries ON languages.id = countries.id JOIN official_languages ON countries.id = official_languages.country_id GROUP BY languages.id, countries.id, official_languages.name ORDER BY languages.name, official_languages.name LIMIT 3;
SELECT DISTINCT l.name, o.country_id FROM languages l JOIN official_languages o ON l.id = o.language_id JOIN countries c ON o.country_id = c.id WHERE c.overall_score ORDER BY c.overall_score DESC LIMIT 3;
SELECT languages.name, countries.overall_score, countries.justice_score, countries.health_score, countries.education_score, countries.economics_score, countries.politics_score, countries.id FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id ORDER BY languages.name DESC;
SELECT languages.name, countries.overall_score AS average_score FROM countries JOIN official_languages ON countries.id = official_languages.country_id ORDER BY countries.overall_score DESC;
SELECT countries.name AS country_name FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id GROUP BY countries.id ORDER BY languages.name DESC LIMIT 1
SELECT countries.name, languages.name AS language_name FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id GROUP BY countries.name ORDER BY languages.name DESC;
SELECT languages.name FROM languages JOIN official_languages ON languages.id = official_languages.language_id WHERE countries.id IS NULL
SELECT l.name FROM languages l JOIN official_languages o ON l.id = o.language_id WHERE o.country_id IS NULL
SELECT countries.name FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE languages.name IS NULL
SELECT countries.name FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE countries.id IS NULL
SELECT languages.name FROM languages JOIN countries ON languages.id = countries.id WHERE countries.overall_score > 95 AND countries.overall_score < 90;
