SELECT Addresses.county_state_province, Ref_Property_Types.property_type_description, Ref_Room_Types.room_type_description FROM Addresses JOIN Ref_Property_Types ON Addresses.address_id = Properties.property_type_code JOIN Ref_Room_Types ON Rooms.room_type_code = Ref_Room_Types.room_type_code JOIN Properties ON Addresses.address_id = Properties.property_address_id JOIN Ref_Property_Types ON Properties.property_type_code = Ref_Property_Types.property_type_code JOIN Ref_Room_Types ON Rooms.room_type_code = Ref_Room_Types.room_type_code JOIN Users ON Users.user_address_id = Addresses.address_id JOIN Ref_User_Categories ON Users.user_category_code = Ref_User_Categories.user_category_code;
SELECT feature_description FROM Features;
SELECT Features.feature_name, Features.feature_description FROM Features JOIN Property_Features ON Features.feature_id = Property_Features.feature_id WHERE Features.feature_name = 'rooftop'
SELECT Features.feature_name, Features.feature_description FROM Features JOIN Property_Features ON Features.feature_id = Property_Features.feature_id JOIN Properties ON Property_Features.property_id = Properties.property_id WHERE Properties.property_type_code = (SELECT property_type_code FROM Ref_Property_Types) ORDER BY Features.feature_name ASC LIMIT 1;
SELECT F.feature_name, F.feature_description FROM Features F JOIN Property_Features PF ON F.feature_id = PF.feature_id JOIN Properties P ON PF.property_id = P.property_id JOIN Ref_Property_Types PT ON P.property_type_code = PT.property_type_code JOIN Ref_Room_Types RT ON P.room_type_code = RT.room_type_code JOIN Rooms R ON P.room_number = R.room_number JOIN Ref_User_Categories UC ON P.owner_user_id = UC.user_category_code JOIN Users U ON P.owner_user_id = U.user_id WHERE P.date_on_market IS NULL OR P.date_off_market IS NULL ORDER BY F.feature_name, F.feature_description LIMIT 1;
SELECT MIN(room_count) FROM Rooms;
SELECT MIN(room_count) FROM Properties;
SELECT COUNT(*) AS total_properties FROM Properties WHERE garage_yn OR parking_lots;
SELECT COUNT(*) FROM Properties WHERE garage_yn OR parking_lots;
SELECT Users.first_name, Users.last_name FROM Users JOIN Addresses ON Addresses.address_id = Users.user_address_id JOIN Ref_Property_Types ON Addresses.property_type_code = Ref_Property_Types.property_type_code JOIN Ref_Room_Types ON Addresses.room_type_code = Ref_Room_Types.room_type_code JOIN Ref_User_Categories ON Users.user_category_code = Ref_User_Categories.user_category_code JOIN Ref_Property_Types ON Addresses.property_type_code = Ref_Property_Types.property_type_code JOIN Ref_Room_Types ON Addresses.room_type_code = Ref_Room_Types.room_type_code JOIN Ref_User_Categories ON Users.user_category_code = Ref_User_Categories.user_category_code WHERE Users.first_name LIKE '%Mother%' OR Users.last_name LIKE '%Mother%'
SELECT DISTINCT user_category_code, user_address_id, user_first_name, user_last_name, user_login_name FROM Users INNER JOIN Ref_Property_Types ON Users.user_address_id = Properties.property_address_id INNER JOIN Ref_Property_Types ON Users.user_address_id = Properties.property_address_id INNER JOIN Ref_Property_Types ON Users.user_address_id = Properties.property_address_id INNER JOIN Ref_Property_Types ON Users.user_address_id = Properties.property_address_id INNER JOIN Ref_Property_Types ON Users.user_address_id = Properties.property_address_id INNER JOIN Ref_Property_Types ON Users.user_address_id = Properties.property_address_id;
