SELECT u.user_id, u.first_name, u.last_name FROM Users u JOIN User_Property_History h ON u.user_id = h.user_id JOIN Properties p ON h.property_id = p.property_id JOIN Property_Features pf ON p.property_id = pf.property_id JOIN Features f ON pf.feature_id = f.feature_id JOIN Ref_Property_Types pt ON p.property_type_code = pt.property_type_code JOIN Ref_Room_Types rt ON p.room_type_code = rt.room_type_code WHERE h.datestamp >= '2023-01-01' AND h.datestamp <= '2023-02-01' AND u.first_name != '' AND u.last_name != '' GROUP BY u.user_id, u.first_name, u.last_name
