SELECT Name FROM author JOIN book ON author.Author_ID = book.Author_ID WHERE book.Release_date IS NOT NULL AND book.Sale_Amount > 100000;
SELECT book.Title, author.Name, press.Name AS publisher_name FROM book JOIN author ON book.Author_ID = author.Author_ID JOIN press ON book.Press_ID = press.Press_ID ORDER BY book.Sale_Amount DESC LIMIT 3;
SELECT Title, Author.Name, Press.Name AS Press_name FROM book INNER JOIN author ON book.Author_ID = author.Author_ID INNER JOIN press ON book.Press_ID = press.Press_ID WHERE book.Sale_Amount > 0;
SELECT press.Name, press.Month_Profits_billion + press.Year_Profits_billion AS total_book_sale_amount FROM press INNER JOIN book ON press.Press_ID = book.Press_ID;
SELECT press.Name, press.Month_Profits_billion + press.Year_Profits_billion AS total_book_sale_amount FROM press INNER JOIN book ON book.Press_ID = press.Press_ID;
SELECT press.Name, COUNT(book.Book_Series) AS book_count, book.Release_date FROM press JOIN book ON book.Press_ID = press.Press_ID GROUP BY press.Name HAVING book.Sale_Amount > 1000;
SELECT press.Name, COUNT(book.Sale_Amount) AS book_count FROM press JOIN book ON press.Press_ID = book.Press_ID GROUP BY press.Name
SELECT author.Name AS Author, book.Release_date AS Release_date FROM book JOIN author ON book.Author_ID = author.Author_ID ORDER BY book.Release_date DESC;
SELECT author.Name, book.Release_date FROM book INNER JOIN author ON book.Author_ID = author.Author_ID;
SELECT Name, Gender FROM author INNER JOIN book ON author.Author_ID = book.Author_ID GROUP BY Name, Gender ORDER BY Release_date DESC LIMIT 1;
SELECT author.Name, author.Gender FROM author JOIN book ON author.Author_ID = book.Author_ID ORDER BY book.Release_date DESC;
SELECT author.Name FROM author JOIN book ON author.Author_ID = book.Author_ID WHERE book.Press_ID = (SELECT Press_ID FROM press WHERE Name = 'Accor' AND Month_Profits_billion IS NULL OR Year_Profits_billion IS NULL)
SELECT author.Name FROM author JOIN book ON author.Author_ID = book.Author_ID WHERE book.Press_ID = (SELECT Press_ID FROM press WHERE Name = 'Accor') AND book.Release_date IS NULL;
SELECT author.Name, press.Month_Profits_billion AS Year_Profits_billion FROM author JOIN press ON author.Author_ID = press.Author_ID WHERE press.Month_Profits_billion IS NOT NULL AND press.Month_Profits_billion > 0
SELECT press.Name, press.Month_Profits_billion AS monthly_profit, press.Year_Profits_billion AS yearly_profit FROM press INNER JOIN book ON press.Press_ID = book.Press_ID WHERE book.Author_ID IS NOT NULL AND book.Release_date IS NOT NULL AND book.Sale_Amount > 2000000;
