SELECT authors.author_name, documents.document_name, documents.document_description, documents.other_details FROM Documents INNER JOIN Authors ON Documents.author_name = Authors.author_name;
SELECT Authors.author_name, Authors.other_details, Ref_Staff_Roles.staff_role_description FROM Authors JOIN Ref_Staff_Roles ON Authors.author_name = Ref_Staff_Roles.staff_role_description;
SELECT D.author_name, D.document_name, D.document_description, D.other_details, D.process_outcome_code, D.process_status_code FROM Documents D JOIN Documents_Processes DP ON D.document_id = DP.document_id JOIN Process_Outcomes PO ON DP.process_outcome_code = PO.process_outcome_code JOIN Process_Status PS ON DP.process_status_code = PS.process_status_code JOIN Business_Processes BP ON DP.process_id = BP.process_id JOIN Staff_in_Processes SP ON DP.process_id = SP.process_id JOIN Staff staff ON SP.staff_id = staff.staff_id JOIN Ref_Staff_Roles R ON SP.staff_role_code = R.staff_role_code JOIN Authors A ON D.author_name = A.author_name WHERE D.author_name = 'Addison Denesik' AND D.document_name IS NOT NULL;
