SELECT invoice_id, COUNT(p.payment_id) AS payment_count FROM Invoices INNER JOIN Payments ON Invoices.invoice_id = Payments.invoice_id GROUP BY invoice_id
SELECT COUNT(DISTINCT invoice_id) FROM Invoices;
SELECT invoice_id, invoice_status, invoice_details, distinct payment_details FROM Invoices INNER JOIN Payments ON Invoices.invoice_id = Payments.invoice_id INNER JOIN Staff_in_Meetings ON Payments.payment_id = Staff_in_Meetings.meeting_id GROUP BY invoice_id, invoice_status, invoice_details ORDER BY COUNT(payments.payment_id) DESC LIMIT 1;
SELECT invoice_id, invoice_status, invoice_details FROM Invoices INNER JOIN Payments ON Invoices.invoice_id = Payments.invoice_id WHERE Payments.payment_details.payment_status = 'paid' ORDER BY invoice_status DESC LIMIT 1;
SELECT COUNT(*) AS total_staff FROM Staff;
SELECT COUNT(*) FROM Staff
SELECT Agencies.agency_id, COUNT(Staff.staff_id) AS staff_count FROM Agencies INNER JOIN Staff ON Agencies.agency_id = Staff.agency_id;
SELECT agencies.agency_id, COUNT(staff.staff_id) AS num_staff_per_agency FROM Agencies JOIN Staff ON Agencies.agency_id = Staff.agency_id GROUP BY Agencies.agency_id
SELECT agency_details, staff_details FROM Agencies JOIN Staff ON Agencies.agency_id = Staff.agency_id GROUP BY agency_id ORDER BY staff_details ASC;
SELECT a.agency_id, a.detail FROM Agencies a JOIN Staff s ON a.agency_id = s.agency_id JOIN Staff_in_Meetings m ON s.staff_id = m.staff_id GROUP BY a.agency_id ORDER BY a.agency_id DESC LIMIT 1;
SELECT m.meeting_outcome, COUNT(m.meeting_outcome) AS count_meeting_outcome FROM Meetings m JOIN Staff_in_Meetings s ON m.meeting_id = s.meeting_id GROUP BY m.meeting_outcome
SELECT COUNT(DISTINCT meeting_outcome) AS meeting_outcome_count, meeting_outcome FROM Meetings JOIN Staff ON Meetings.meeting_id = Staff_in_Meetings.meeting_id JOIN Agencies ON Staff.agency_id = Agencies.agency_id JOIN Clients ON Clients.client_id = Meetings.client_id JOIN Staff_in_Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id;
SELECT Clients.client_id, COUNT(Meetings.client_id) AS meeting_count FROM Clients INNER JOIN Meetings ON Clients.client_id = Meetings.client_id GROUP BY Clients.client_id;
SELECT COUNT(DISTINCT client_id) AS total_meetings_per_client FROM Clients;
SELECT Clients.client_id, COUNT(Meetings.client_id) AS count_meetings, Meetings.meeting_type AS meeting_type_code FROM Clients JOIN Clients ON Clients.client_id = Clients.client_id JOIN Meetings ON Clients.client_id = Meetings.client_id GROUP BY Clients.client_id;
SELECT DISTINCT meeting_type, COUNT(*) AS total_meetings FROM Meetings GROUP BY meeting_type;
SELECT Meetings.meeting_id, Meetings.client_id, Meetings.meeting_outcome, Meetings.meeting_type, Meetings.billable_yn, Meetings.start_date_time, Meetings.end_date_time, Meetings.purpose_of_meeting, Meetings.other_details FROM Meetings INNER JOIN Clients ON Clients.client_id = Meetings.client_id;
SELECT Meetings.meeting_id, Meetings.client_id, Meetings.meeting_outcome, Meetings.meeting_type, Clients.client_id, Clients.client_details FROM Meetings JOIN Clients ON Meetings.client_id = Clients.client_id;
SELECT m.meeting_id, s.staff_id, COUNT(s.staff_id) AS num_staff_per_meeting FROM Meetings m JOIN Staff s ON m.client_id = s.client_id GROUP BY m.meeting_id
SELECT COUNT(DISTINCT staff.staff_id) AS count_of_staff_per_meeting FROM Staff JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id;
SELECT staff_id, COUNT(meeting_id) AS meeting_attendance_count FROM Staff INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id GROUP BY staff_id HAVING COUNT(meeting_id) > 0 ORDER BY staff_id;
SELECT staff_id FROM Staff_in_Meetings JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id WHERE Meetings.client_id IS NOT NULL AND Meetings.meeting_type IS NOT NULL AND Meetings.billable_yn IS NOT NULL AND Meetings.start_date_time IS NOT NULL AND Meetings.end_date_time IS NOT NULL AND Meetings.purpose_of_meeting IS NOT NULL AND Meetings.other_details IS NOT NULL AND Staff_in_Meetings.staff_id IS NOT NULL
SELECT COUNT(*) AS count_of_staff_attended_meeting FROM Staff JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id;
SELECT COUNT(DISTINCT staff.staff_id) FROM Staff JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id;
SELECT COUNT(*) FROM Staff INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id WHERE Staff_in_Meetings.meeting_id IS NULL;
SELECT COUNT(*) FROM Staff JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id WHERE Staff_in_Meetings.meeting_type IS NULL;
SELECT Clients.client_id, Clients.client_details, Clients.sic_code, Clients.agency_id, Clients.client_details FROM Clients INNER JOIN Agencies ON Clients.agency_id = Agencies.agency_id INNER JOIN Clients INNER JOIN Staff ON Clients.client_id = Staff.client_id INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id INNER JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id INNER JOIN Invoices ON Meetings.client_id = Invoices.client_id;
SELECT c.client_id, c.client_details, m.meeting_type, m.purpose_of_meeting, m.billable_yn, m.start_date_time, m.end_date_time, m.meeting_outcome, m.other_details, s.staff_id FROM Clients c JOIN Meetings m ON c.client_id = m.client_id JOIN Staff s ON m.staff_id = s.staff_id WHERE m.billable_yn = 'Y' OR m.invoice_id = (SELECT invoice_id FROM Invoices WHERE invoice_status = 'A' OR invoice_status = 'M') ORDER BY c.client_id;
SELECT staff.staff_id, staff.staff_details, meetings.meeting_outcome, meetings.purpose_of_meeting, meetings.billable_yn, meetings.start_date_time, meetings.end_date_time, meetings.meeting_type, meetings.payment_details FROM Staff INNER JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id INNER JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id WHERE meetings.client_id IN (SELECT client_id FROM Clients WHERE Clients.sic_code = 's') AND meetings.billable_yn = 'Y'
SELECT s.staff_id, s.staff_details FROM Staff s JOIN Staff_in_Meetings st ON s.staff_id = st.staff_id JOIN Meetings m ON st.meeting_id = m.meeting_id WHERE m.client_id IN (SELECT client_id FROM Clients WHERE Clients.client_id IN (SELECT client_id FROM Invoices WHERE Invoices.invoice_status = 'attended' AND Invoices.invoice_details LIKE '%s%')) AND s.staff_details LIKE '%s'
SELECT C.client_id, C.sic_code, C.agency_id FROM Clients C JOIN Meetings M ON C.client_id = M.client_id WHERE M.meeting_outcome = 'attended' AND M.meeting_type IS NULL OR M.meeting_outcome IS NULL;
SELECT C.client_id, C.sic_code, C.agency_id, S.staff_id FROM Clients C JOIN Staff S ON C.agency_id = S.agency_id JOIN Staff_in_Meetings S2 ON S.staff_id = S2.staff_id JOIN Meetings M ON S2.meeting_id = M.meeting_id WHERE M.client_id = C.client_id AND M.meeting_outcome = 'attended' AND M.meeting_type = 'meeting' AND M.billable_yn = 'yes' AND M.invoice_status = 'invoice'
SELECT M.start_date_time, M.end_date_time, C.client_id, S.staff_id FROM Meetings M INNER JOIN Clients C ON M.client_id = C.client_id INNER JOIN Staff S ON S.staff_id = M.staff_id;
SELECT m.start_date_time, m.end_date_time, s.staff_id, c.client_id, c.client_details, s.staff_details FROM Meetings m JOIN Staff s ON m.meeting_id = s.meeting_id JOIN Clients c ON m.client_id = c.client_id JOIN Staff_in_Meetings s_in ON s.staff_id = s_in.staff_id JOIN Agencies a ON s.agency_id = a.agency_id;
